  padding-bottom: var(--custom-card-gap);
  border-bottom: 1px solid var(--custom-separator);
}

.recent-post-item:last-child {
  border-bottom: none;
}

/* 封面区域 - 窄横幅 */
.post_cover {
  width: 100%;
  height: 180px;
  margin-bottom: 24px;
  border-radius: 8px;
  overflow: hidden;
  position: relative;
}

.post_cover a {
  display: block;
  width: 100%;
  height: 100%;
}

.post-bg {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

