Page.content:
:root {
  --default-cursor: url(https://img.hehey.top/images/user/default.cur);
  --pointer-cursor: url(https://img.hehey.top/images/user/pointer.cur);
  --theme-color: #1677B3;
  --global-bg: #F2F6FC;
  --global-bg-lighter: rgba(242, 246, 252, .4);
  --global-bg-bolder: rgba(242, 246, 252, .8);
  --r: 22;
  --g: 119;
  --b: 179;
  --main: rgb(var(--r), var(--g), var(--b));
  --second: var(--white);
  --cover-bg: rgb(var(--r), var(--g), var(--b));
  --main-lighter: rgba(var(--r), var(--g), var(--b), .4);
  --main-bolder: rgba(var(--r), var(--g), var(--b), .8);
  --box-shadow: 3px 6px 6px -3px rgba(45, 45, 45, .05);
  /* --box-shadow: 0 2px 3px 1px rgba(45, 45, 45, .05); */
  --main-shadow: 3px 6px 6px -3px rgba(var(--r), var(--g), var(--b), .2);
  /* --main-shadow: 0 2px 3px 1px rgba(var(--r), var(--g), var(--b), .2); */
  --card-border: 1px solid var(--tab-button-bg);
  --card-border-dashed: 2px dashed var(--tab-button-hover-bg);
  --border-radius: .5rem;
  --light-text: #FF7242;
  --light-text-bg: rgba(255, 149, 63, .1);
  --backdrop-filter: saturate(240%) blur(20px);
}

[data-theme='dark'] {
  --global-bg: #000;
  --global-bg-lighter: rgba(0, 0, 0, .4);
  --global-bg-bolder: rgba(0, 0, 0, .8);
  --main: #5C5C5C;
  --second: #EEE !important;
  --main-lighter: rgba(92, 92, 92, .4);
  --main-bolder: rgba(92, 92, 92, .8);
  --main-shadow: 0 2px 3px 1px rgba(92, 92, 92, .2);
  --light-text: #FFB449;
  --light-text-bg: rgba(255, 180, 73, .1);
}

[data-theme='dark'] #web_bg::before,
[data-theme='dark'] #footer::before,
[data-theme='dark'] #page-header::before {
  display: none;
}

/* 鼠标样式 */
html {
  cursor: var(--default-cursor, default), default !important;
}

body {
  cursor: var(--default-cursor, default), default !important;
}

#recent-posts .recent-post-items .recent-post-item>.recent-post-info>.article-meta-wrap>.post-meta-date {
  cursor: var(--default-cursor, default), default !important;
}

ul::before,
li::before {
  cursor: var(--default-cursor, default), default !important;
}

#pagination span {
  cursor: var(--default-cursor, default), default !important;
}

a,
img,
button,
svg,
canvas,
select {
  cursor: var(--pointer-cursor), pointer !important;
}

i.scroll-down-effects {
  cursor: var(--pointer-cursor), pointer !important;
}

.reward-button {
  cursor: var(--pointer-cursor), pointer !important;
}

#pagination a {
  cursor: var(--pointer-cursor), pointer !important;
}

/* 图片预览 */
.fancybox,
.fancybox-button,
.fancybox-content,
.fancybox__caption,
.fancybox__viewport,
.fancybox__slide .fancybox__content,
.fancybox__thumbs .carousel__slide,
.fancybox__carousel.is-draggable .fancybox__slide,
.fancybox__carousel.is-draggable .fancybox__slide .fancybox__content {
  cursor: var(--pointer-cursor), pointer !important;
}

/* 代码块 */
#article-container figure.highlight .highlight-tools .expand~.copy-button,
#article-container figure.highlight .highlight-tools .expand,
#article-container .code-expand-btn {
  cursor: var(--pointer-cursor), pointer !important;
}

/* 评论与回复 */
.switch-btn,
.vcol *,
.v[data-class=v] .vicon,
.v[data-class=v] .vbtn,
.vat,
.vemojis *,
.vcontent.expand {
  cursor: var(--pointer-cursor), pointer !important;
}

/* twikoo */
.tk-action-icon,
.tk-panel .tk-tab,
.tk-expand,
.tk-pagination-pager,
.OwO .OwO-body,
.OwO .OwO-body .OwO-items .OwO-item,
.OwO .OwO-body .OwO-bar .OwO-packages li {
  cursor: var(--pointer-cursor), pointer !important;
}

/* 文章轮播 */
.swiper-pagination-clickable .swiper-pagination-bullet {
  cursor: var(--pointer-cursor), pointer !important;
}

#rightmenu .rightmenu-group .rightmenu-item {
  cursor: var(--pointer-cursor), pointer !important;
}

/* pace进度条 */
.pace {
  z-index: 2000;
  position: fixed;
  top: 4px;
  left: 0;
  right: 0;
  margin: auto;
  width: 100px;
  height: 8px;
  border-radius: 8px;
  background: var(--global-bg);
  overflow: hidden
}

.pace .pace-progress {
  display: block;
  position: absolute;
  top: 0;
  right: 100%;
  height: 100%;
  width: 100%;
  background: linear-gradient(215deg, var(--theme-color) 0%, #00c4b6 100%);
}

.pace.pace-inactive {
  opacity: 0;
  top: -8px;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

.layout {
  padding: 1rem;
  z-index: 1;
  background: var(--global-bg);
}

#post-comment {
  margin-top: 20px;
}

body.read-mode #post-comment {
  display: none;
}

#comment-mask {
  display: none;
}

#comment-close {
  display: none;
}

@media screen and (max-width: 900px) {
  .layout>div:first-child {
    width: 100% !important;
    z-index: 1;
    height: fit-content;
  }
}

@media screen and (min-width: 901px) {

