#aside-content .card-categories ul.card-category-list>.card-category-list-item {
  width: calc(50% - .25rem);
  margin-top: .5rem;
}

#aside-content .card-archives ul.card-archive-list>.card-archive-list-item a,
#aside-content .card-categories ul.card-category-list>.card-category-list-item a {
  border-radius: var(--border-radius);
  background: var(--global-bg);
  display: flex;
  flex-direction: column;
}

#aside-content .card-archives ul.card-archive-list>.card-archive-list-item a span,
#aside-content .card-categories ul.card-category-list>.card-category-list-item a span {
  overflow: visible;
}

#aside-content .card-webinfo .webinfo .webinfo-item i {
  width: 1rem;
  margin-right: .25rem;
  text-align: center;
}

#aside-content .card-widget.card-info .card-info-top {
  display: flex;
  margin-bottom: .5rem;
}

#aside-content .card-widget.card-info .card-info-img {
  width: 120px;
  height: 120px;
  margin-left: .25rem;
}

#aside-content .card-widget.card-info #card-info-hello {
  width: 120px;
  height: 120px;
  padding: .8rem;
  margin-right: .25rem;
  text-align: justify;
  color: var(--font-color);
  background: var(--global-bg);
  border-radius: var(--border-radius);
}

#aside-content .card-widget.card-info .card-info-img img {
  width: 100%;
  height: 100%;
  padding: .5rem;
  background: var(--global-bg);
  border-radius: var(--border-radius);
}

#aside-content .card-info .author-info-name {
  font-weight: bold;
  background: var(--global-bg);
  border-radius: var(--border-radius);
}

#aside-content .card-info .author-info-description {
  padding: .5rem;
  margin: .5rem 0;
  background: var(--global-bg);
  border-radius: var(--border-radius);
}

#aside-content .card-widget.card-info .site-data {
  margin: .5rem 0;
}

#aside-content .card-widget.card-posts .item-headline * {
  display: none;
}

#aside-content .card-widget.card-posts>:not(:first-child) .item-headline {
  margin: 1rem 0 .5rem 0;
  border-top: var(--card-border-dashed);
}

/* 归档、分类、朋友圈 */
.article-sort {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  border: none;
  padding: 0;
  margin: 0;
}

.article-sort-title {
  margin: 0;
  padding: 0;
  border: none;
}

.article-sort-item {
  width: 100%;
  padding: .5rem;
  margin: .3rem 0;
  background: var(--global-bg);
  border-radius: var(--border-radius);
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

.article-sort-item.year {
  width: 100%;
  margin: .5rem 0;
  color: var(--second);
  background: var(--main) !important;
}

.article-sort-title::before,
.article-sort-title::after,
.article-sort-item::before {
  display: none;
}

@media screen and (min-width: 901px) {
  .article-sort-item:not(.year):not(#fc-state):not(#fc-more) {
    width: calc(50% - .25rem);
  }
}

.article-sort-item-img {
  height: 80px;
  width: 120px;
  border-radius: var(--border-radius);
}

/* 朋友圈 */
.fc-article-sort .article-sort-item-img {
  width: 80px !important;
  height: 80px !important;
}

.fc-article-sort .article-sort-item-time {
  bottom: .8rem;
}

.fc-article-sort .fc-article-author {
  margin-left: .5em;
}

#fc-more {
  width: 40%;
  margin: 1rem auto !important;
  flex-direction: column;
  cursor: var(--pointer-cursor), pointer !important;
}

#fc-more:hover {
  width: 60%;
}

#fc-more i.fas::before {
  content: "∞";
}

/* 个人文章列表层 */
#fc-overlay,
#fc-overshow {
  position: fixed;
  width: 100%;
  height: 100%;
}

#fc-overlay {
  z-index: 998;
  top: 0;
  left: 0;
  background: var(--global-bg-lighter);
  backdrop-filter: var(--backdrop-filter);
}

#fc-overlay.hidden {
  left: 100%;
}

#fc-overshow {
  bottom: 0;
  left: 0;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
  z-index: 999;
}

#fc-overshow.hidden {
  bottom: 100%;
}

.fc-overshow {
  text-align: center;
  border-radius: 1rem;
  position: absolute;
  width: clamp(20rem, 50%, 30rem);
  min-height: 20rem;
  left: 50%;
  top: 50%;
  -webkit-transform: translate(-50%, -50%);
  -moz-transform: translate(-50%, -50%);
  -ms-transform: translate(-50%, -50%);
  -o-transform: translate(-50%, -50%);
  transform: translate(-50%, -50%);
  box-shadow: var(--card-box-shadow);
  background: var(--card-bg);
}

.fc-overshow .fc-overshow-head {
  margin-top: -55px;
}

.fc-overshow .fc-overshow-head+div {
  padding-top: .8rem;
  color: var(--text-highlight-color);
  font-weight: bold;
}

.fc-overshow p {
  margin-top: .5rem;
  width: 100%;
  position: relative;
}

.fc-overshow p span {
  color: #858585;
  position: absolute;
  bottom: -1rem;
  right: .5rem;
  z-index: 1;
  font-style: italic;
}

.fc-overshow .fc-overshow-content {
  text-align: left;
  font-size: 95%;
  padding: 0 1rem 1rem;
}

.fc-overshow .fc-overshow-content a {
  -webkit-line-clamp: 1;
  line-height: 2;
  font-weight: bold;
}

#fc-overshow .fc-overshow-close {
  width: 100%;
  height: 100%;
}

.article-sort-item-info {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 85%;
}

.article-sort-item-title {
  color: var(--theme-color) !important;
  font-size: 1.2em;
  line-height: 1.5;
  -webkit-transform: none !important;
  -moz-transform: none !important;
  -ms-transform: none !important;
  -o-transform: none !important;
  transform: none !important;
}

@media screen and (max-width: 600px) {
  .article-sort-item-time {
    display: none;
  }

  .article-sort-item-img {
    width: 100px !important;
  }
}

@media (min-width: 901px) and (max-width: 1200px) {
  .article-sort-item-time {
    display: none;
  }

  .article-sort-item-img {
    width: 100px !important;
  }
}

.article-sort-item-categories i,
.article-sort-item-tags i {
  margin-right: .2em;
}

.article-sort-item-categories {
  margin-right: .5em;
}

.article-sort-item .article-meta-wrap {
  font-size: 95%;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
}

.article-sort-item .article-meta__link {
  display: none;
}

.article-sort-item-title:hover {
  color: var(--light-text) !important;
}

.article-sort-item-time {
  position: absolute;
  right: .8rem;
  bottom: .4rem;
}

.article-sort-item-index {
  opacity: .2;
  position: absolute;
  top: .5rem;
  right: .5rem;
  font-style: italic;
  font-size: 2.5rem;
  line-height: 1.5rem;
}

.article-sort-item-tags {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  line-height: 1.2;
}

.article-sort-item-categories a.article-meta__categories,
.article-sort-item-tags a.article-meta__tags {
  padding: .2em;
  color: var(--font-color);
  border-radius: .4em;
}

.article-sort-item-categories a.article-meta__categories:hover,
.article-sort-item-tags a.article-meta__tags:hover {
  color: var(--second);
  background: var(--main);
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
}

/* 分类目录条、标签目录条 */
#catalog-bar {
  padding: .4rem .8rem;
  border-radius: var(--border-radius);
  display: flex;
  border: var(--card-border);
  margin-bottom: 1rem;
  justify-content: space-between;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#catalog-bar:hover {
  border-color: var(--main);
}

#catalog-bar i {
  line-height: inherit;
}

#catalog-list {
  /* 分类/标签较少时，可以选择不设置 width，居中显示 catalog-list-item */
  /* width: 100%; */
  margin: 0 .5rem;
  display: flex;
  white-space: nowrap;
  overflow-x: scroll;
}

#catalog-list::-webkit-scrollbar {
  display: none;
}

.catalog-list-item a {
  margin: 0 .2em;
  padding: .2em .3em .3em;
  font-weight: bold;
  border-radius: var(--border-radius);
  color: var(--font-color);
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

.catalog-list-item sup {
  margin-left: .1em;
}

.catalog-list-item:hover a {
  background: var(--main);
  color: var(--second);
}

.catalog-list-item.selected a {
  background: var(--light-text);
  color: var(--second);
}

a.catalog-more {
  min-width: fit-content;
  font-weight: bold;
  color: var(--font-color);
}

a.catalog-more:hover {
  color: var(--main);
}

/* 目录 */
#aside-content #card-toc .toc-content {
  display: inline-block;
  margin: 0;
  width: 100%;
  max-height: 60vh;
}

#aside-content #card-toc .toc-content a.toc-link:hover {
  color: var(--second);
  border-radius: var(--border-radius);
  background: var(--main-lighter);
  -webkit-transform: scale(1.05);
  -moz-transform: scale(1.05);
  -ms-transform: scale(1.05);
  -o-transform: scale(1.05);
  transform: scale(1.05);
}

#aside-content #card-toc .toc-content .toc-link.active {
  font-weight: bold;
  border-radius: var(--border-radius);
  color: var(--second);
  border-left-color: var(--main);
  background: var(--main) !important;
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
  -webkit-transform: scale(1.05);
  -moz-transform: scale(1.05);
  -ms-transform: scale(1.05);
  -o-transform: scale(1.05);
  transform: scale(1.05);
}

#aside-content #card-toc .toc-content .toc-link {
  font-size: 95%;
}

/* 翻页 */
#pagination {
  flex: auto;
  width: 100%;
}

#pagination .page-number.current {
  color: var(--white);
  background: var(--light-text);
}

#pagination a.extend,
#pagination .page-number,
#pagination span {
  color: var(--text-highlight-color);
  background: var(--card-bg);
  border-radius: var(--border-radius);
  height: 2rem;
  width: 2rem;
  text-align: center;
  line-height: 2rem;
  border: var(--card-border);
  -webkit-box-shadow: var(--box-shadow);
  -moz-box-shadow: var(--box-shadow);
  -ms-box-shadow: var(--box-shadow);
  -o-box-shadow: var(--box-shadow);
  box-shadow: var(--box-shadow);
}

#pagination a.page-number:hover,
#pagination a.extend:hover {
  color: var(--second);
  background: var(--main);
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
  border-color: var(--main);
}

.pagination span.space {
  border: none !important;
  box-shadow: none !important;
  font-weight: bold;
  background: transparent !important;
}

#pagination a.extend.prev {
  width: 4.5rem;
  float: left;
  padding: 0 .8rem 0 .2rem;
  border-top-left-radius: 1rem;
  border-bottom-left-radius: 1rem;
}

#pagination a.extend.next {
  width: 4.5rem;
  float: right;
  padding: 0 .2rem 0 .8rem;
  border-top-right-radius: 1rem;
  border-bottom-right-radius: 1rem;
}

#pagination a.extend.prev .pagination-prev {
  opacity: 0;
  display: inline;
  color: var(--second);
  margin-right: -2em;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#pagination a.extend.prev:hover .pagination-prev {
  opacity: 1;
  margin-right: 0;
}

#pagination a.extend.next .pagination-next {
  opacity: 0;
  display: inline;
  color: var(--second);
  margin-left: -2em;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#pagination a.extend.next:hover .pagination-next {
  opacity: 1;
  margin-left: 0;
}

.toPageGroup {
  display: inline-block;
  position: relative;
  width: unset !important;
  height: 2rem !important;
  line-height: unset !important;
}

.pagination .toPageGroup:hover input,
.pagination .toPageGroup input:focus {
  width: 5rem;
  border-color: var(--main);
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
}

.pagination input {
  width: 2rem;
  height: 2rem;
  border-radius: var(--border-radius);
  border: var(--card-border);
  outline-style: none;
  padding-left: 1rem;
  color: var(--text-highlight-color);
  background: var(--tab-button-bg);
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

.toPageGroup:hover a#toPageButton,
.toPageGroup:focus a#toPageButton,
.toPageGroup:focus-within a#toPageButton {
  width: 1.6rem;
  height: 1.6rem;
  right: .4rem;
  top: .2rem;
  background: var(--card-bg);
  border-radius: calc(var(--border-radius) / 2);
  opacity: .2;
}

a#toPageButton {
  display: flex;
  position: absolute;
  width: 2rem;
  height: 2rem;
  right: 0;
  top: 0;
  border-radius: var(--border-radius);
  justify-content: center;
  align-items: center;
  color: var(--font-color);
  background: var(--card-bg);
  pointer-events: none;
  cursor: var(--pointer-cursor), pointer !important;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

a#toPageButton.haveValue {
  opacity: 1 !important;
  pointer-events: all;
}

a#toPageButton.haveValue:hover {
  color: var(--second);
  background: var(--main);
}

/* 上下一篇文章 */
#pagination.pagination-post {
  border-radius: var(--border-radius);
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

#pagination .prev-post .label,
#pagination .next-post .label {
  font-size: 1rem;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

#pagination .prev-post .prev_info,
#pagination .next-post .next_info {
  font-size: 1.1rem;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

#pagination .prev-post {
  border-right: var(--card-border);
}

#pagination .next-post {
  border-left: var(--card-border);
}

#pagination .prev-post:hover img,
#pagination .next-post:hover img {
  opacity: .1 !important;
}

#pagination .prev-post:hover a,
#pagination .next-post:hover a {
  background: var(--main);
  color: var(--second);
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
}

#pagination .prev-post:hover .label,
#pagination .next-post:hover .label,
#pagination .prev-post:hover .prev_info,
#pagination .next-post:hover .next_info {
  opacity: 0;
}

#pagination .content {
  opacity: 0;
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  padding: 0 1rem;
  color: var(--second);
  text-align: justify;
  word-break: break-all;
  -webkit-line-clamp: 3;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
  -webkit-transform: translateY(-50%);
  -moz-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
  -o-transform: translateY(-50%);
  transform: translateY(-50%);
}

#pagination .prev-post:hover .content,
#pagination .next-post:hover .content {
  opacity: 1;
}

/* 推荐文章 */
.relatedPosts>.relatedPosts-list .content {
  position: relative;
}

.relatedPosts>.relatedPosts-list>div {
  border-radius: var(--border-radius);
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

.relatedPosts>.relatedPosts-list .content .date {
  font-size: 1rem;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

.relatedPosts>.relatedPosts-list .content .title {
  font-size: 1.1rem;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
}

.relatedPosts>.relatedPosts-list>div:hover .cover {
  opacity: .1;
}

.relatedPosts>.relatedPosts-list>div:hover {
  background: var(--main);
  color: var(--second);
  -webkit-box-shadow: var(--main-shadow);
  -moz-box-shadow: var(--main-shadow);
  -ms-box-shadow: var(--main-shadow);
  -o-box-shadow: var(--main-shadow);
  box-shadow: var(--main-shadow);
}

.relatedPosts>.relatedPosts-list>div:hover .content .date,
.relatedPosts>.relatedPosts-list>div:hover .content .title {
  opacity: 0;
}

.relatedPosts>.relatedPosts-list .content .info {
  opacity: 0;
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
  padding: 0 1rem;
  color: var(--second);
  text-align: justify;
  word-break: break-all;
  -webkit-line-clamp: 3;
  display: -webkit-box;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-transition: all .6s ease-in-out;
  -moz-transition: all .6s ease-in-out;
  -ms-transition: all .6s ease-in-out;
  -o-transition: all .6s ease-in-out;
  transition: all .6s ease-in-out;
  -webkit-transform: translateY(-50%);
  -moz-transform: translateY(-50%);
  -ms-transform: translateY(-50%);
  -o-transform: translateY(-50%);
  transform: translateY(-50%);
}

.relatedPosts>.relatedPosts-list>div:hover .content .info {
  opacity: 1;
}

/* 加粗字体颜色 */
b,
strong {
  color: var(--light-text);
}

/* 赞赏 */
.post-reward {
  margin-top: 1rem;
}

.comment-head {
  position: relative;
}

.comment-protocol {
  position: absolute;
  right: 0;
  display: inline-block;
  font-weight: bold;
  font-size: 1.43em;
}


/* 音乐播放器 */
#article-container .aplayer {
  border-radius: var(--border-radius) !important;
}

/* 页脚 */
#footer {
  background: linear-gradient(180deg, transparent 0, var(--card-bg) 60%);
}

#footer::before {
  display: none;
}

#footer #footer-wrap {
  padding: 0;
  color: var(--text-highlight-color);
}

#footer #footer-banner {
  background: var(--tab-button-bg);
  border: var(--card-border);
}

#footer #footer-banner #footer-banner-container a {
  margin: 0 .5rem;
