  -ms-transition: all .3s linear;
  -o-transition: all .3s linear;
  transition: all .3s linear;
}

[data-theme="dark"] #nav #hotkey #mode-button i.fa-moon {
  opacity: 1;
}

[data-theme="dark"] #nav #hotkey #mode-button i.fa-sun {
  opacity: 0;
  color: #FF7242 !important;
}

