  height: 40px;
  margin: 0;
  color: var(--second) !important;
  background: var(--main);
}

#nav #hotkey #top-button .scroll-percent {
  display: none;
  font-family: UnidreamLED;
  line-height: 1.8em;
  width: 100%;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#nav #hotkey #top-button .scroll-percent+i {
  display: block;
  line-height: 1.8em;
  width: 100%;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#nav #hotkey #top-button.show-percent .scroll-percent {
  display: block;
}

#nav #hotkey #top-button.show-percent .scroll-percent+i {
  display: none;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#nav #hotkey #top-button:hover .scroll-percent {
  display: none;
}

#nav #hotkey #top-button:hover .scroll-percent+i {
  display: block;
  line-height: 2.2em;
  -webkit-transition: all .3s ease-in-out;
  -moz-transition: all .3s ease-in-out;
  -ms-transition: all .3s ease-in-out;
  -o-transition: all .3s ease-in-out;
  transition: all .3s ease-in-out;
}

#nav #hotkey #top-button i::before {
  content: attr(data-percent);
  position: absolute;
  line-height: 1.8em;
  left: 0;
  right: 0;
  top: 0;
  font-size: 95%;
  font-weight: normal;
  font-family: UnidreamLED;
}

#nav #hotkey #top-button:hover i::before {
  content: '\f062';
  position: relative;
  font-size: unset;
  font-weight: unset;
  font-family: unset;
}

/* 右下角设置按钮 */
#rightside {
  z-index: 100;
  opacity: 1 !important;
  width: 1200px;
  max-width: 80vw;
  min-height: 250px;
  max-height: 90vh;
  right: 50%;
  bottom: 50%;
  padding: 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  border-radius: calc(var(--border-radius) * 2);
  border: var(--card-border);
  -webkit-box-shadow: var(--box-shadow);
  -moz-box-shadow: var(--box-shadow);
  -ms-box-shadow: var(--box-shadow);
  -o-box-shadow: var(--box-shadow);
  box-shadow: var(--box-shadow);
  background: var(--global-bg-bolder);
